// Opt-in native smoke; only uses the disposable UTF-8 file generated by the harness.
import router from "@/router";
import type { SmokeConfig } from "@/domain/e2e/desktop-smoke";
import { enqueueProjectFiles } from "@/services/external-file-open";
import { invokeBackend } from "@/services/desktop-bridge";
import { useLocalProjectStore } from "@/stores/local-project";
import { useWorkbenchStore } from "@/stores/workbench";
import * as monaco from "@/services/monaco-runtime.js";

async function until<T>(read: () => T | undefined | false | null, label: string, timeout: number): Promise<T> {
  const end = performance.now() + timeout;
  while (performance.now() < end) {
    const value = read();
    if (value) return value;
    await new Promise<void>((resolve) => setTimeout(resolve, 50));
  }
  throw new Error(`Timed out waiting for ${label}`);
}

export async function largeTextScenario(config: SmokeConfig, log: { done(step: string): void }) {
  const path = config.largeText!.filePath;
  const project = useLocalProjectStore();
  const workbench = useWorkbenchStore();
  const tab = workbench.openView("projects");
  if (!tab) throw new Error("Could not open project workspace");
  await router.push({ name: "projects" });
  try {
    enqueueProjectFiles([path]);
    const pre = () => document.querySelector<HTMLElement>(".project-large-text__content");
    await until(() => pre()?.textContent?.includes(`FIRST ${config.nonce}`), "first text chunk", config.timeoutMs);
    log.done("70 MiB synthetic SQL opened in the real read-only chunk viewer");
    const first = pre()!.textContent;
    const initial = await invokeBackend<{ version: string; totalBytes: number }>("local_fs_read_external_text_chunk", { path, offset: 0 });
    if (new TextEncoder().encode(first ?? "").length > 512 * 1024) throw new Error("first chunk exceeds budget");
    if (monaco.editor.getModels().some((model) => model.uri.fsPath === path)) throw new Error("large text created a full editor model");
    if (project.activeDocument?.content !== "") throw new Error("preview leaked into editable document content");
    log.done("only one bounded chunk is displayed; no Monaco model or editable document content");
    const wrap = document.querySelector<HTMLElement>(".project-large-text__scroll .el-scrollbar__wrap");
    if (!wrap || wrap.scrollHeight <= wrap.clientHeight) throw new Error("preview cannot scroll");
    wrap.scrollTop = 200;
    if (wrap.scrollTop === 0) throw new Error("preview scrollTop stayed at zero");
    log.done("long text scrolls inside the viewer");

    const buttons = () => [...document.querySelectorAll<HTMLButtonElement>(".project-large-text__toolbar button")];
    buttons()[1].click();
    await until(() => pre()?.textContent && pre()!.textContent !== first, "next chunk", config.timeoutMs);
    if (!pre()!.textContent?.includes("中文🙂")) throw new Error("UTF-8 text lost across chunks");
    await until(() => !buttons()[0].disabled, "previous enabled", config.timeoutMs);
    buttons()[0].click();
    await until(() => pre()?.textContent === first, "previous chunk", config.timeoutMs);
    log.done("next and previous chunks preserve Chinese and emoji without accumulating text");

    pre()!.dispatchEvent(new KeyboardEvent("keydown", { key: "s", ctrlKey: true, metaKey: true, bubbles: true, cancelable: true }));
    const unchanged = await invokeBackend<{ version: string }>("local_fs_read_external_text_chunk", { path, offset: 0, expectedVersion: initial.version });
    if (unchanged.version !== initial.version || project.activeDocument?.content !== "") throw new Error("save key changed the file");
    log.done("save shortcut leaves the original file and editable buffer unchanged");

    project.closeDocument(path);
    await until(() => !pre(), "preview removed after close", config.timeoutMs);
    log.done("closing the document removes the viewer");
  } finally {
    project.closeDocument(path);
    workbench.closeTab(tab.id, true);
  }
}
